// G2 guard — fail closed. Validates BEFORE any execution.
const item = $input.first();
const raw = (item.json.chatInput ?? item.json.input ?? '').toString();
const MAX = 2000;
const CHARSET = /^[A-Za-z0-9 _.,:;!?@/#%()'\"\n-]*$/;
const DENY = [/rm\s+-rf/i, /\/etc\//i, /~\/\.ssh/i, /\.env/i, /secret/i, /token/i, /password/i, /--dangerous/i, /\bsudo\b/i, /\bcurl\b/i, /\bwget\b/i, /\bssh\b/i, /base64/i, />\s*\//];
let allowed = true; let reason = 'ok';
if (raw.length === 0) { allowed = false; reason = 'empty'; }
else if (raw.length > MAX) { allowed = false; reason = 'too long'; }
else if (!CHARSET.test(raw)) { allowed = false; reason = 'charset'; }
else { for (const re of DENY) { if (re.test(raw)) { allowed = false; reason = 'denylisted'; break; } } }
return [{ json: { input: raw, allowed, reason } }];

// G1 no-shell execution (execFile argv) + G3 sandbox cwd + G4 least-priv + G5 timeout/cap + redaction.
// PREREQ: n8n instance env NODE_FUNCTION_ALLOW_BUILTIN=child_process,os,path,fs
// Auth (user-approved trade-off, 2026-06-05): copy ONLY ~/.claude/.credentials.json into the sandbox
// HOME so claude can auth via the subscription login, while filesystem access stays confined to the
// sandbox (G3 preserved — no ~/.ssh / real-home exposure).
const { execFileSync } = require('child_process');
const os = require('os');
const path = require('path');
const fs = require('fs');
const input = $input.first().json.input;
const realHome = os.homedir();
const sandbox = path.join(realHome, '.n8n-claude-bridge', 'sandbox');
fs.mkdirSync(sandbox, { recursive: true });
try {
  const credDir = path.join(sandbox, '.claude');
  fs.mkdirSync(credDir, { recursive: true });
  fs.copyFileSync(path.join(realHome, '.claude', '.credentials.json'), path.join(credDir, '.credentials.json'));
} catch (e) { /* missing creds -> claude fails to auth; surfaced in output */ }
const env = { PATH: process.env.PATH, HOME: sandbox };
if (process.env.ANTHROPIC_API_KEY) env.ANTHROPIC_API_KEY = process.env.ANTHROPIC_API_KEY;
let out;
try {
  out = execFileSync('claude', ['-p', input, '--permission-mode', 'plan'], { cwd: sandbox, env, timeout: 60000, maxBuffer: 1048576, encoding: 'utf8' });
} catch (e) {
  out = (e && e.killed) ? '[the assistant timed out]' : ('[error running the assistant] ' + (e && e.message ? String(e.message).slice(0, 200) : ''));
}
out = String(out).replace(/sk-[A-Za-z0-9_-]{8,}|ghp_[A-Za-z0-9]{8,}|AKIA[0-9A-Z]{12,}|-----BEGIN[\s\S]*?-----END[^-]*-----/g, '[redacted]');
if (out.length > 4000) out = out.slice(0, 4000) + '…';
return [{ json: { output: out } }];
